// Hand-written. Not generated by Speakeasy.
//
// Validates the element values of enum-typed lists.
//
// Speakeasy emits a OneOf validator for a scalar enum but not for the elements
// of a list of enums, so a misspelled value reached Authlete unchecked: about a
// minute of retries, then a generic 500 that does not mention the value or the
// attribute.
//
// The allowed values are not written out here. Each one delegates to the enum
// type the SDK already generates from the specification, whose UnmarshalJSON
// rejects anything outside the set. That means this can never drift: when
// Authlete adds a value, regeneration updates the switch statement and this
// starts accepting it with no edit here. A hand-copied list would eventually
// reject a value that had become valid, which is worse than not validating.
//
// Two lists are deliberately absent -- service.supported_snses and
// client.response_modes. Their enums are inline in the specification rather
// than named, so no Go type is generated and the only option would be a
// hand-copied list carrying exactly that drift risk.
//
// client.client_registration_types is absent for a different reason: the
// specification marks it read-only, so a practitioner cannot set it and there
// is nothing to get wrong. Only the service-level
// supported_client_registration_types is settable.
package validators

import (
	"encoding/json"
	"strconv"

	"github.com/authlete/terraform-provider-authlete/internal/sdk/models/shared"
)

// checker reports whether a value is a member of its enum.
type checker func(string) bool

func accepts[T json.Unmarshaler](newT func() T) checker {
	return func(v string) bool {
		return newT().UnmarshalJSON([]byte(strconv.Quote(v))) == nil
	}
}

// EnumLists maps a Terraform attribute name to the enum its elements belong to.
// Both resources are covered by one table because no attribute name means
// different enums on service and client.
var EnumLists = map[string]checker{
	"supported_grant_types":                      accepts(func() *shared.GrantType { return new(shared.GrantType) }),
	"supported_response_types":                   accepts(func() *shared.ResponseType { return new(shared.ResponseType) }),
	"supported_service_profiles":                 accepts(func() *shared.ServiceProfile { return new(shared.ServiceProfile) }),
	"supported_displays":                         accepts(func() *shared.Display { return new(shared.Display) }),
	"supported_token_auth_methods":               accepts(func() *shared.ClientAuthMethod { return new(shared.ClientAuthMethod) }),
	"supported_revocation_auth_methods":          accepts(func() *shared.ClientAuthMethod { return new(shared.ClientAuthMethod) }),
	"supported_introspection_auth_methods":       accepts(func() *shared.ClientAuthMethod { return new(shared.ClientAuthMethod) }),
	"supported_claim_types":                      accepts(func() *shared.ClaimType { return new(shared.ClaimType) }),
	"supported_backchannel_token_delivery_modes": accepts(func() *shared.DeliveryMode { return new(shared.DeliveryMode) }),
	"supported_attachments":                      accepts(func() *shared.AttachmentType { return new(shared.AttachmentType) }),
	"supported_client_registration_types":        accepts(func() *shared.ClientRegistrationType { return new(shared.ClientRegistrationType) }),
	"supported_prompt_values":                    accepts(func() *shared.Prompt { return new(shared.Prompt) }),
	"fapi_modes":                                 accepts(func() *shared.FapiMode { return new(shared.FapiMode) }),
	"grant_types":                                accepts(func() *shared.GrantType { return new(shared.GrantType) }),
	"response_types":                             accepts(func() *shared.ResponseType { return new(shared.ResponseType) }),
}

// Accepts reports whether value is valid for the named attribute, and whether
// the attribute is one this validates at all.
func Accepts(attribute, value string) (ok bool, known bool) {
	check, known := EnumLists[attribute]
	if !known {
		return true, false
	}
	return check(value), true
}
